// spec: specs/customers-pricing.md §12 · кейс .qa/tests/customers/cust-16 (+ регресс cust-14 п.5) · seed: tests/seed.admin.spec.ts
// #ab1b2e (עבר QA 01.11): карточка клиента «test» (0531231235), admin, 1440. Если загрузка orders не удалась — 4 KPI
//   («הזמנה אחרונה», «יתרה פתוחה», «סה"כ רכישות», «מס' הזמנות») показывают «—», а не 0 / ₪0.00, и «הזמנות אחרונות» —
//   «אירעה שגיאה בטעינת ההזמנות. נסה שוב.»; пока идут повторы — скелет; «נסה שוב» после восстановления даёт реальные
//   значения; если данные уже были загружены, а повторная загрузка упала — значения остаются + полоса
//   «לא ניתן לרענן את ההזמנות. מוצגים הנתונים האחרונים שנטענו.» с «נסה שוב».
// Метод: page.route на GET /rest/v1/orders (fulfill 500 / abort / удержание до release()), без sleep. Эталон значений —
//   строка «test» в «לקוחות» и карточка, загруженные в ОТДЕЛЬНОМ контексте (свой кэш), без перехвата: числа меняются,
//   жёстких значений нет. Кадры KPI пишет MutationObserver из addInitScript (window.__qaKpi); скелет — класс animate-pulse.
// Только чтение, ничего не создаёт — @prod-safe.
import { test, expect } from '@playwright/test';
import type { Page, Browser, Route } from '@playwright/test';
import { authFile, rowOf, openList, search, TEST_PHONE } from './_customers';

test.use({ storageState: authFile('admin') });

const TEST_ID = 'a30f4767-3f86-4a49-a441-ecfd2faad6d0'; // «test», тел. 0531231235, «פעיל», с заказами
const TEST_CARD = `/customers/${TEST_ID}`;
const ORDERS = /\/rest\/v1\/orders\?/;
const KPI = ['הזמנה אחרונה', 'יתרה פתוחה', 'סה"כ רכישות', "מס' הזמנות"] as const;
const DASH = '—';
const ERR_TEXT = 'אירעה שגיאה בטעינת ההזמנות. נסה שוב.';
const STALE_TEXT = 'לא ניתן לרענן את ההזמנות. מוצגים הנתונים האחרונים שנטענו.';
const RETRY = 'נסה שוב';
const ZERO_RE = /^(0|₪0\.00)$/;
const BIDI = /[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g; // невидимые RTL/LTR-метки в суммах
const clean = (s: string) => s.replace(BIDI, '').replace(/\s+/g, ' ').trim();
const SLOW = 30_000; // повторы запроса orders при ошибке ~16 с

type Kpi = Record<string, string>;
type Frame = { t: number; kpi: Kpi };

// ── наблюдатель KPI (в странице): значение плитки или SKEL/EMPTY/NONE ─────────────────────────
function observer(labels: string[]) {
  const w = window as unknown as { __qaObs?: boolean; __qaKpi: unknown[]; __qaKpiNow: () => unknown };
  if (w.__qaObs) return;
  w.__qaObs = true;
  w.__qaKpi = [];
  const pulse = (el: Element) => el.matches('[class*=animate-pulse]') || !!el.querySelector('[class*=animate-pulse]');
  const snap = () => {
    const main = document.querySelector('main');
    if (!main || !/^\/customers\/[^/]+$/.test(location.pathname)) return null;
    const kpi: Record<string, string> = {};
    for (const l of labels) {
      const leaf = [...main.querySelectorAll('*')].find((x) => !x.children.length && (x.textContent || '').trim() === l);
      const box = leaf?.parentElement;
      if (!box) { kpi[l] = 'NONE'; continue; }
      kpi[l] = (box as HTMLElement).innerText.replace(l, '').trim().split('\n')[0].trim() || (pulse(box) ? 'SKEL' : 'EMPTY');
    }
    return kpi;
  };
  let last = '';
  const rec = () => {
    try {
      const kpi = snap();
      if (!kpi) return;
      const k = JSON.stringify(kpi);
      if (k !== last) { last = k; w.__qaKpi.push({ t: Math.round(performance.now()), kpi }); }
    } catch { /* кадр без main */ }
  };
  w.__qaKpiNow = snap;
  const start = () => { new MutationObserver(rec).observe(document, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['class'] }); rec(); };
  if (document.documentElement) start(); else document.addEventListener('readystatechange', start, { once: true });
}

const installObserver = (page: Page) => page.addInitScript(observer, [...KPI]);
const frames = (page: Page) => page.evaluate(() => (window as unknown as { __qaKpi: Frame[] }).__qaKpi);
const kpiNow = (page: Page) => page.evaluate(() => (window as unknown as { __qaKpiNow: () => Kpi | null }).__qaKpiNow());

/** Значение плитки KPI (элемент сразу после подписи). */
const tile = (page: Page, label: string) =>
  page.getByRole('main').getByText(label, { exact: true }).locator('xpath=following-sibling::*[1]');

/** Кадры, где хоть одна плитка показала 0 / ₪0.00. */
const zeroFrames = (log: Frame[]) => log.flatMap((f) =>
  Object.entries(f.kpi).filter(([, v]) => ZERO_RE.test(v)).map(([k, v]) => `${f.t}ms ${k}: ${v}`));

async function waitCard(page: Page) {
  await expect(page.getByRole('heading', { level: 1, name: 'test', exact: true })).toBeVisible({ timeout: SLOW });
}

async function expectAllDash(page: Page) {
  for (const l of KPI) await expect(tile(page, l), `«${l}» = «—»`).toHaveText(DASH, { timeout: SLOW });
}

async function expectKpi(page: Page, ref: Kpi) {
  for (const l of KPI) await expect(tile(page, l), `«${l}» = эталон`).toHaveText(ref[l], { timeout: SLOW });
}

/** Ответ orders = 500 на каждый GET (включая повторы). Возвращает снятие перехвата. */
async function fail500(page: Page) {
  const h = (route: Route) => route.request().method() === 'GET'
    ? route.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA-AUTO forced 500"}' })
    : route.fallback();
  await page.route(ORDERS, h);
  return () => page.unroute(ORDERS, h);
}

/** Держит GET orders до release(); first — первый запрос пойман. */
async function hold(page: Page) {
  let open!: () => void;
  const gate = new Promise<void>((r) => (open = r));
  let gotFirst!: () => void;
  const first = new Promise<void>((r) => (gotFirst = r));
  let released = false;
  await page.route(ORDERS, async (route) => {
    if (route.request().method() === 'GET' && !released) { gotFirst(); await gate; }
    await route.fallback().catch(() => { /* страница закрыта */ });
  });
  return {
    first,
    async release() {
      const mark = (await frames(page)).length;
      const resp = page.waitForResponse((r) => ORDERS.test(r.url()) && r.request().method() === 'GET', { timeout: SLOW });
      released = true;
      open();
      await resp;
      return mark;
    },
  };
}

/**
 * Эталон без перехвата, в отдельном контексте (свой кэш, чтобы не превратить сценарий «ошибка» в «обновление»):
 * строка «test» в «לקוחות» («מס' הזמנות», «יתרה») и 4 KPI карточки; KPI сверяются со строкой списка.
 */
async function reference(browser: Browser): Promise<Kpi> {
  const ctx = await browser.newContext({ storageState: authFile('admin'), viewport: { width: 1440, height: 900 } });
  try {
    const page = await ctx.newPage();
    await openList(page);
    await search(page, 'test');
    const row = rowOf(page, TEST_PHONE);
    await expect(row).toContainText('₪', { timeout: SLOW });
    const text = clean(await row.innerText());
    const m = text.match(new RegExp(`${TEST_PHONE} ([\\d,]+) (-?₪-?[\\d,]+\\.\\d{2})`));
    expect(m, `строка test в «לקוחות»: «מס' הזמנות» и «יתרה» после телефона — «${text}»`).not.toBeNull();
    const [, listCount, listBalance] = m!;

    const ordersOk = page.waitForResponse((r) => ORDERS.test(r.url()) && r.request().method() === 'GET' && r.ok(), { timeout: SLOW });
    await page.goto(TEST_CARD);
    await waitCard(page);
    await ordersOk;
    await expect(tile(page, "מס' הזמנות")).toHaveText(/^[1-9][\d,]*$/, { timeout: SLOW });
    const ref: Kpi = {};
    for (const l of KPI) ref[l] = (await tile(page, l).innerText()).trim();
    expect(clean(ref["מס' הזמנות"]), 'карточка «מס\' הזמנות» = строка в «לקוחות»').toBe(listCount);
    expect(clean(ref['יתרה פתוחה']), 'карточка «יתרה פתוחה» = «יתרה» в «לקוחות»').toBe(listBalance);
    expect(ref['סה"כ רכישות']).toMatch(/₪[\d,]+\.\d{2}/);
    expect(ref['הזמנה אחרונה']).toMatch(/^\d{2}\.\d{2}\.\d{4}$/);
    for (const l of KPI) expect(ref[l], `эталон «${l}» не «—» и не 0`).not.toMatch(/^(—|0|₪0\.00)$/);
    return ref;
  } finally {
    await ctx.close();
  }
}

test.describe('כרטיס לקוח — מדדים כשטעינת ההזמנות נכשלת (#ab1b2e)', () => {
  test.beforeEach(async ({ page }) => { await installObserver(page); });

  test('orders 500 — 4 המדדים «—», «אירעה שגיאה בטעינת ההזמנות. נסה שוב.», אף פעם לא 0 / ₪0.00 #ab1b2e @desktop @prod-safe', async ({ page }) => {
    await fail500(page);
    await page.goto(TEST_CARD);
    await waitCard(page);
    await expect(page.getByRole('main').getByText(ERR_TEXT, { exact: true })).toBeVisible({ timeout: SLOW });
    await expect(page.getByRole('main').getByRole('button', { name: RETRY })).toBeVisible();
    await expectAllDash(page);
    expect(zeroFrames(await frames(page)), 'KPI ни в одном кадре не 0 / ₪0.00').toEqual([]);
  });

  test('orders abort — שלד בזמן הניסיונות החוזרים, אחר כך «—» ×4, בלי 0 / ₪0.00 #ab1b2e @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    let aborted = 0;
    await page.route(ORDERS, (route) => {
      if (route.request().method() !== 'GET') return route.fallback();
      aborted++;
      return route.abort('failed');
    });
    await page.goto(TEST_CARD);
    await waitCard(page);
    await expect.poll(async () => Object.values((await kpiNow(page)) || {}), { message: 'во время повторов KPI — скелет' })
      .toEqual(KPI.map(() => 'SKEL'));
    await expectAllDash(page);
    await expect(page.getByRole('main').getByText(ERR_TEXT, { exact: true })).toBeVisible();
    expect(aborted, 'запрос orders действительно обрывался').toBeGreaterThan(0);

    const log = await frames(page);
    const firstDash = log.findIndex((f) => KPI.every((l) => f.kpi[l] === DASH));
    expect(firstDash, 'был кадр «—» ×4').toBeGreaterThan(0);
    const before = log.slice(0, firstDash).flatMap((f) =>
      Object.entries(f.kpi).filter(([, v]) => !['SKEL', 'NONE'].includes(v)).map(([k, v]) => `${f.t}ms ${k}: ${v}`));
    expect(before, 'до «—» KPI только скелет (ни 0, ни ₪0.00, ни частичных «—»)').toEqual([]);
    expect(zeroFrames(log), 'KPI ни в одном кадре не 0 / ₪0.00').toEqual([]);
  });

  test('orders 500 — «לקוחות» ← ⋮ ← «כרטיס לקוח»: בשורה «—», בכרטיס «—» ×4 #ab1b2e @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await fail500(page);
    await openList(page);
    await search(page, 'test');
    const row = rowOf(page, TEST_PHONE);
    await expect(row).toBeVisible({ timeout: SLOW });
    await expect(row, 'в строке нет сумм ₪ при ошибке orders').not.toContainText('₪', { timeout: SLOW });
    await expect.poll(async () => clean(await row.innerText()), { message: '«מס\' הזמנות» и «יתרה» в строке = «—»', timeout: SLOW })
      .toContain(`${TEST_PHONE} ${DASH} ${DASH}`);

    await row.getByRole('button', { name: 'פעולות' }).click();
    await page.getByRole('menuitem', { name: 'כרטיס לקוח' }).click();
    await page.waitForURL(`**${TEST_CARD}`);
    await waitCard(page);
    await expectAllDash(page);
    await expect(page.getByRole('main').getByText(ERR_TEXT, { exact: true })).toBeVisible();
    expect(zeroFrames(await frames(page)), 'KPI ни в одном кадре не 0 / ₪0.00').toEqual([]);
  });

  test('אחרי שגיאה: הסרת היירוט → «נסה שוב» → ערכים אמיתיים (כמו בשורה ב«לקוחות»), בלי 0 בדרך #ab1b2e @desktop @prod-safe', async ({ page, browser }) => {
    test.setTimeout(120_000);
    const ref = await reference(browser);
    const restore = await fail500(page);
    await page.goto(TEST_CARD);
    await waitCard(page);
    await expectAllDash(page);
    const retry = page.getByRole('main').getByRole('button', { name: RETRY });
    await expect(retry).toBeVisible();

    await restore();
    const ok = page.waitForResponse((r) => ORDERS.test(r.url()) && r.request().method() === 'GET' && r.ok(), { timeout: SLOW });
    await retry.click();
    await ok;
    await expectKpi(page, ref);
    await expect(page.getByRole('main').getByText(ERR_TEXT, { exact: true })).toHaveCount(0);
    expect(zeroFrames(await frames(page)), 'ни в одном кадре 0 / ₪0.00 (и при переходе «—» → значения)').toEqual([]);
  });

  test('orders מתעכב — שלד עד התשובה, בלי 0 / ₪0.00 / «—», אחר כך ערכים אמיתיים #ab1b2e #08cb68 @desktop @prod-safe', async ({ page, browser }) => {
    test.setTimeout(120_000);
    const ref = await reference(browser);
    const ord = await hold(page);
    await page.goto(TEST_CARD);
    await ord.first;
    await waitCard(page);
    await expect.poll(async () => Object.values((await kpiNow(page)) || {}), { message: 'KPI до ответа orders — скелет' })
      .toEqual(KPI.map(() => 'SKEL'));

    const mark = await ord.release();
    await expectKpi(page, ref);

    const log = await frames(page);
    const shown = log.slice(0, mark).flatMap((f) =>
      Object.entries(f.kpi).filter(([, v]) => !['SKEL', 'NONE'].includes(v)).map(([k, v]) => `${f.t}ms ${k}: ${v}`));
    expect(shown, 'до ответа orders ни одного значения KPI (0 / ₪0.00 / «—»)').toEqual([]);
    expect(zeroFrames(log), 'KPI ни в одном кадре не 0 / ₪0.00').toEqual([]);
  });

  test('נטען בהצלחה, אחר כך 500 בטעינה חוזרת («חזרה ללקוחות» → ⋮ → «כרטיס לקוח») — המדדים נשמרים + פס «לא ניתן לרענן…» עם «נסה שוב» #ab1b2e @desktop @prod-safe', async ({ page, browser }) => {
    test.setTimeout(120_000);
    const ref = await reference(browser);
    const ok = page.waitForResponse((r) => ORDERS.test(r.url()) && r.request().method() === 'GET' && r.ok(), { timeout: SLOW });
    await page.goto(TEST_CARD);
    await waitCard(page);
    await ok;
    await expectKpi(page, ref);

    await fail500(page);
    await page.getByText('חזרה ללקוחות').click();
    await page.waitForURL(/\/customers$/);
    await search(page, 'test');
    const row = rowOf(page, TEST_PHONE);
    await expect(row).toBeVisible({ timeout: SLOW });
    await row.getByRole('button', { name: 'פעולות' }).click();
    const refetch = page.waitForResponse((r) => ORDERS.test(r.url()) && r.request().method() === 'GET' && r.status() === 500, { timeout: SLOW });
    await page.getByRole('menuitem', { name: 'כרטיס לקוח' }).click();
    await page.waitForURL(`**${TEST_CARD}`);
    await waitCard(page);
    await refetch;

    const banner = page.getByRole('main').getByText(STALE_TEXT, { exact: true });
    await expect(banner, 'полоса «לא ניתן לרענן…»').toBeVisible({ timeout: SLOW });
    await expect(page.getByRole('main').getByRole('button', { name: RETRY }), '«נסה שוב» в полосе').toBeVisible();
    await expectKpi(page, ref);
    await expect(page.getByRole('main').getByText(ERR_TEXT, { exact: true })).toHaveCount(0);

    const log = await frames(page);
    expect(log.filter((f) => KPI.some((l) => f.kpi[l] === DASH)).map((f) => `${f.t}ms ${JSON.stringify(f.kpi)}`),
      'при неудачном обновлении KPI не сбрасываются в «—»').toEqual([]);
    expect(zeroFrames(log), 'KPI ни в одном кадре не 0 / ₪0.00').toEqual([]);
  });
});
